    'en' => [
        'title' => 'Free Online Loan Calculator (Fixed Installments) | uToolsGo',
        'meta'  => 'Simulate a loan with fixed installments (amortization schedule) online for free. See the installment amount, total paid and total interest.',
        'h1'    => 'Loan Calculator',
        'subtitle' => 'Simulate fixed installments using the standard amortization formula for auto loans, personal loans and similar financing.',
        'fieldLabels' => ['valor' => 'Loan amount', 'taxa' => 'Interest rate (% per month)', 'parcelas' => 'Number of installments'],
        'strings' => [
            'valorParcela' => 'Each installment amount', 'totalPago' => 'Total paid at the end', 'totalJuros' => 'Total interest',
