        'optionLabels' => ['quadrado' => 'Quadrado', 'retangulo' => 'Retângulo', 'triangulo' => 'Triângulo', 'circulo' => 'Círculo', 'trapezio' => 'Trapézio', 'paralelogramo' => 'Paralelogramo', 'losango' => 'Losango'],
        'strings' => [
