                'trapezio' => ['Base maior (B)', 'Base menor (b)', 'Altura (h)', 'Lado (perna, l)'],
                'paralelogramo' => ['Base (a)', 'Altura (h)', 'Lado (b)'],
                'losango' => ['Diagonal maior (D)', 'Diagonal menor (d)'],
