        'optionLabels' => ['KB' => 'KB', 'MB' => 'MB', 'GB' => 'GB', 'Kbps' => 'Kbps (kilobits/s)', 'Mbps' => 'Mbps (megabits/s)', 'MBps' => 'MB/s (megabytes/s)'],
