'bmr-calculator' => [
    'pt' => [
        'title' => 'Calculadora de TMB e Gasto Calórico Diário (TDEE) | uToolsGo',
        'meta'  => 'Calcule sua Taxa de Metabolismo Basal (TMB) e o gasto calórico diário total (TDEE) pela fórmula de Mifflin-St Jeor, com sugestão de calorias para emagrecer, manter ou ganhar peso.',
        'h1'    => 'Calculadora de TMB e Gasto Calórico Diário',
        'subtitle' => 'Informe sexo, idade, peso, altura e nível de atividade para calcular sua Taxa de Metabolismo Basal e o gasto calórico total estimado.',
        'fieldLabels' => ['sexo' => 'Sexo', 'idade' => 'Idade (anos)', 'peso' => 'Peso (kg)', 'altura' => 'Altura (cm)', 'atividade' => 'Nível de atividade física'],
