],
'ideal-weight-calculator' => [
    'pt' => [
        'title' => 'Calculadora de Peso Ideal (4 Fórmulas) | uToolsGo',
        'meta'  => 'Calcule seu peso ideal por 4 fórmulas clássicas (Robinson, Miller, Devine e Hamwi) a partir da sua altura, online e grátis.',
        'h1'    => 'Calculadora de Peso Ideal',
