'box-shadow-generator' => [
    'pt' => [
        'title' => 'Gerador de Box Shadow CSS Online | uToolsGo',
        'meta'  => 'Crie sombras CSS (box-shadow) visualmente, ajuste deslocamento, desfoque, espalhamento e cor, e copie o código pronto.',
        'h1'    => 'Gerador de Box Shadow CSS',
        'subtitle' => 'Ajuste visualmente a sombra do seu elemento e copie o código CSS pronto.',
        'fieldLabels' => [
