    'en' => [
        'title' => 'Free Freelancer Hourly Rate Calculator | uToolsGo',
        'meta'  => 'Calculate how much to charge per hour as a freelancer, factoring in desired income, business costs, billable hours and time off.',
        'h1'    => 'Freelancer Hourly Rate Calculator',
        'subtitle' => 'Find out how much to charge per hour to reach the net income you want.',
        'fieldLabels' => [
            'rendaDesejadaFr' => 'Desired monthly net income', 'custosMensaisFr' => 'Monthly business costs (tools, taxes, etc.)',
            'horasSemanaisFr' => 'Billable hours per week', 'semanasFeriasFr' => 'Weeks off per year',
        ],
        'strings' => [
