    'pt' => [
        'title' => 'Calculadora de Valor Esperado (EV) de Aposta | uToolsGo',
        'meta'  => 'Calcule o valor esperado (EV) de uma aposta a partir da odd, da probabilidade estimada e do valor apostado. Ferramenta educacional/matemática.',
        'h1'    => 'Calculadora de Valor Esperado (EV)',
        'subtitle' => 'Ferramenta educacional para entender o valor esperado matemático de uma aposta.',
        'fieldLabels' => ['decimalOddsEv' => 'Odd decimal', 'estimatedProbability' => 'Sua probabilidade estimada (%)', 'stakeAmount' => 'Valor apostado (R$)'],
        'strings' => [
