'feriados-2025' => [
    'pt' => [
        'title' => 'Feriados 2025: Veja Todas as Datas e Feriados Nacionais do Brasil | uToolsGo',
        'meta' => 'Calendário completo dos feriados 2025 no Brasil: datas, dias da semana, feriados móveis (Carnaval, Páscoa, Corpus Christi) e dicas de pontes para 2025.',
