'salario-minimo-2024' => [
    'pt' => [
        'title' => 'Salário Mínimo 2024: Valor, GPS e Reajuste | uToolsGo',
        'meta' => 'Salário mínimo 2024: veja o valor oficial, quanto é por dia e por hora, o reajuste em relação a 2023 e os códigos GPS do INSS para autônomo e facultativo em 2024.',
