'equivalent-exposure-calculator' => [
    'pt' => [
        'title' => 'Calculadora de Exposição Equivalente Grátis | uToolsGo',
        'meta'  => 'Calcule a exposição equivalente ao mudar ISO, abertura ou velocidade do obturador, mantendo o mesmo brilho final da foto.',
        'h1'    => 'Calculadora de Exposição Equivalente',
        'subtitle' => 'Informe a exposição original, o que você vai mudar e qual dos outros dois campos deve ser recalculado.',
