    'es' => [
        'title' => 'Calculadora de Costo de Viaje en Auto | uToolsGo',
        'meta' => 'Calcula el combustible, su costo, el total con peajes, el costo por persona y el tiempo de viaje. Admite km o millas, km/L, L/100 km y mpg, y precio por litro o galón.',
        'h1' => 'Calculadora de Costo de Viaje en Auto',
        'subtitle' => 'Indica la distancia, el consumo del vehículo, el precio del combustible, los peajes y cuántas personas dividen el gasto.',
