'recommended-sleep-calculator' => [
    'pt' => [
        'title' => 'Quantas Horas de Sono Preciso por Idade? | uToolsGo',
        'meta' => 'Veja a faixa de horas de sono recomendada para a sua idade segundo a National Sleep Foundation (2015), do recém-nascido ao idoso. Orientação geral.',
        'h1' => 'Calculadora de Horas de Sono Recomendadas',
        'subtitle' => 'Informe a idade e veja a faixa de horas de sono por dia recomendada pela National Sleep Foundation.',
